TextureInfo const& Info(Texture texture) {
    return kInfo[static_cast<int>(texture)];
}

TextureInfo const& Info(int index) {
    return kInfo[index >= 0 && index < kTextures ? index : 0];
}

std::span<Piece const> Pieces() {
    return kPieces;
}

Point Origin(Layer layer) {
    return layer == Layer::Reticle ? Point{kReticleX, kReticleY} : Point{kFieldX, kFieldY};
}

Point PictureToLayer(float x, float y) {
    float const k = kPictureRadius / kLayerSpan;
    return {0.5f + x * k, 0.5f - y * k};
}

bool LayerToTexture(Piece const& piece, Map& out) {
    // The piece's texels to the movie's pixels, inverted: (u, v) = inverse([a c; b d]) * (P - t).
    float const a = piece.map[0];
    float const b = piece.map[1];
    float const c = piece.map[2];
    float const d = piece.map[3];
    float const det = a * d - c * b;
    if (!(std::abs(det) > 1e-12f) || !std::isfinite(det)) {
        return false;
    }
    TextureInfo const& info = Info(piece.texture);
    float const w = static_cast<float>(info.width);
    float const h = static_cast<float>(info.height);
    // The layer's uv to the movie's pixels: P = origin + (U - 0.5, V - 0.5) * span.
    Point const o = Origin(piece.layer);
    float const s = kLayerSpan;
    float const px0 = o.x - 0.5f * s - piece.map[4];  // P - t at U = V = 0
    float const py0 = o.y - 0.5f * s - piece.map[5];
    // texel u = ( d (Px - tx) - c (Py - ty)) / det; texel v = (-b (Px - tx) + a (Py - ty)) / det; then over the size.
    out.u[0] = d * s / det / w;
    out.u[1] = -c * s / det / w;
    out.u[2] = (d * px0 - c * py0) / det / w;
    out.v[0] = -b * s / det / h;
    out.v[1] = a * s / det / h;
    out.v[2] = (-b * px0 + a * py0) / det / h;
    out.clip[0] = piece.clip[0] / w;
    out.clip[1] = piece.clip[1] / h;
    out.clip[2] = piece.clip[2] / w;
    out.clip[3] = piece.clip[3] / h;
    return true;
}

